 void update(){if(list==null)return;JSONArray all=store.jobs();list.update(all);int down=0,wait=0,fail=0,pausable=0,resumable=0;for(JSONObject j:DataStore.objects(all)){String s=j.optString("status");if(s.equals("downloading")){down++;pausable++;}else if(s.equals("queued")){wait++;pausable++;}else if(s.equals("paused")||s.equals("readyQueued")){wait++;if(s.equals("paused")&&!j.optBoolean("readyManaged"))resumable++;}else if(s.equals("failed"))fail++;}
  List<String> parts=new ArrayList<>();if(down>0)parts.add(Loc.f("%d downloading",down));if(wait>0)parts.add(Loc.f("%d waiting",wait));if(fail>0)parts.add(Loc.f("%d need attention",fail));if(free>=0)parts.add(Loc.f("%s free",size(free)));summary.setText(android.text.TextUtils.join(" · ",parts));
  allKind=pausable>0?"pause":resumable>0?"resume":"";allButton.setText(Loc.t(allKind.equals("pause")?"Pause all":"Resume all"));allButton.setContentDescription(allButton.getText());
  tabNote("queue").setText(down>0?Loc.f("%d downloading",down):wait>0?Loc.f("%d waiting",wait):fail>0?Loc.f("%d need attention",fail):Loc.t("Nothing queued"));tabNote("phone").setText(list.savedFiles>0?Loc.f("%d saved",list.savedFiles):Loc.t("Nothing yet"));
  if(!tabs.containsKey(tab))tab=list.active>0?"queue":list.savedFiles>0?"phone":"queue";show();}
 void all(){String kind=allKind;if(kind.isEmpty())return;data.images.execute(()->{String error=null;boolean started=false;for(JSONObject j:DataStore.objects(store.jobs())){String id=j.optString("id"),s=j.optString("status");try{if(kind.equals("pause")){if(s.equals("downloading")||s.equals("queued"))store.pause(id);}else if(s.equals("paused")&&!j.optBoolean("readyManaged")){JSONObject item=data.item(id);if(item!=null){store.enqueue(item);started=true;}}}catch(Exception e){error=String.valueOf(e.getMessage());}}
  if(started)try{startForegroundService(new Intent(this,DownloadService.class));}catch(Exception e){error=String.valueOf(e.getMessage());}String message=error;runOnUiThread(()->{if(message!=null)Toast.makeText(this,message,Toast.LENGTH_LONG).show();update();});});}
